import Database from 'better-sqlite3';
import path from 'path';

// Resolve the database path in the project directory
const dbPath = path.join(process.cwd(), 'chat.db');
const db = new Database(dbPath);

// Enable WAL mode for better performance and concurrency
db.pragma('journal_mode = WAL');

// Initialize database schema
db.exec(`
  CREATE TABLE IF NOT EXISTS messages (
    room TEXT NOT NULL,
    seq INTEGER NOT NULL,
    user TEXT NOT NULL,
    text TEXT NOT NULL,
    ts INTEGER NOT NULL,
    PRIMARY KEY (room, seq)
  );
`);

export interface Message {
  room: string;
  seq: number;
  user: string;
  text: string;
  ts: number;
}

// In-memory active subscribers registry
// Map from room name to a Set of callback functions
type MessageCallback = (msg: Message) => void;
const subscribers = new Map<string, Set<MessageCallback>>();

export function subscribe(room: string, callback: MessageCallback): () => void {
  if (!subscribers.has(room)) {
    subscribers.set(room, new Set());
  }
  subscribers.get(room)!.add(callback);

  // Return unsubscribe function
  return () => {
    const roomSubs = subscribers.get(room);
    if (roomSubs) {
      roomSubs.delete(callback);
      if (roomSubs.size === 0) {
        subscribers.delete(room);
      }
    }
  };
}

export function getSubscriberCount(room: string): number {
  return subscribers.get(room)?.size ?? 0;
}

export function publishMessage(room: string, user: string, text: string): Message {
  const ts = Date.now();

  // Run SQLite transaction to get next seq and insert message atomically
  const msg = db.transaction(() => {
    const row = db.prepare('SELECT COALESCE(MAX(seq), 0) as maxSeq FROM messages WHERE room = ?').get(room) as { maxSeq: number } | undefined;
    const nextSeq = (row?.maxSeq ?? 0) + 1;

    db.prepare('INSERT INTO messages (room, seq, user, text, ts) VALUES (?, ?, ?, ?, ?)')
      .run(room, nextSeq, user, text, ts);

    return {
      room,
      seq: nextSeq,
      user,
      text,
      ts
    };
  })();

  // Fan-out to active subscribers of this room
  const roomSubs = subscribers.get(room);
  if (roomSubs) {
    for (const callback of roomSubs) {
      try {
        callback(msg);
      } catch (err) {
        console.error('Error in subscriber callback:', err);
      }
    }
  }

  return msg;
}

export function getMessagesAfter(room: string, seq: number): Message[] {
  return db.prepare('SELECT room, seq, user, text, ts FROM messages WHERE room = ? AND seq > ? ORDER BY seq ASC')
    .all(room, seq) as Message[];
}

export function getRecentMessages(room: string, limit = 50): Message[] {
  const rows = db.prepare('SELECT room, seq, user, text, ts FROM messages WHERE room = ? ORDER BY seq DESC LIMIT ?')
    .all(room, limit) as Message[];
  return rows.reverse();
}

import type { RequestHandler } from "@builder.io/qwik-city";
import { publishMessage } from "~/lib/chat";

export const onPost: RequestHandler = async (ev) => {
  const { params, json, parseBody } = ev;
  const room = params.room;

  // Validate room parameter
  if (!room || !/^[A-Za-z0-9_-]+$/.test(room)) {
    return json(400, { error: "Invalid room name" });
  }

  let body: any;
  try {
    body = await parseBody();
  } catch (err) {
    return json(400, { error: "Malformed JSON body" });
  }

  if (!body || typeof body !== 'object') {
    return json(400, { error: "Invalid JSON body" });
  }

  const { user, text } = body;

  if (typeof user !== 'string' || typeof text !== 'string') {
    return json(400, { error: "Fields 'user' and 'text' must be strings" });
  }

  const trimmedUser = user.trim();
  const trimmedText = text.trim();

  if (trimmedUser.length < 1 || trimmedUser.length > 64) {
    return json(400, { error: "Field 'user' must be 1 to 64 characters long after trimming" });
  }

  if (trimmedText.length < 1 || trimmedText.length > 2000) {
    return json(400, { error: "Field 'text' must be 1 to 2000 characters long after trimming" });
  }

  const msg = publishMessage(room, trimmedUser, trimmedText);

  return json(201, {
    room: msg.room,
    seq: msg.seq,
    user: msg.user,
    text: msg.text,
    ts: msg.ts
  });
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { getSubscriberCount } from "~/lib/chat";

export const onGet: RequestHandler = async (ev) => {
  const { params, json } = ev;
  const room = params.room;

  // Validate room parameter
  if (!room || !/^[A-Za-z0-9_-]+$/.test(room)) {
    return json(400, { error: "Invalid room name" });
  }

  return json(200, {
    room,
    subscribers: getSubscriberCount(room)
  });
};

import type { RequestHandler } from "@builder.io/qwik-city";
import { subscribe, getMessagesAfter, getRecentMessages, type Message } from "~/lib/chat";

export const onGet: RequestHandler = async (ev) => {
  const { params, request, headers, getWritableStream, signal, json } = ev;
  const room = params.room;

  // Validate room parameter
  if (!room || !/^[A-Za-z0-9_-]+$/.test(room)) {
    return json(400, { error: "Invalid room name" });
  }

  if (signal.aborted) {
    return;
  }

  // Parse Last-Event-ID header
  const lastEventIdStr = request.headers.get("last-event-id");
  let lastEventId: number | null = null;
  if (lastEventIdStr !== null) {
    const parsed = parseInt(lastEventIdStr, 10);
    if (!isNaN(parsed)) {
      lastEventId = parsed;
    }
  }

  let initialMessages: Message[];
  if (lastEventId !== null) {
    initialMessages = getMessagesAfter(room, lastEventId);
  } else {
    initialMessages = getRecentMessages(room, 50);
  }

  // Set SSE response headers
  headers.set("Content-Type", "text/event-stream");
  headers.set("Cache-Control", "no-cache, no-transform");
  headers.set("Connection", "keep-alive");

  const writableStream = getWritableStream();
  const writer = writableStream.getWriter();
  const encoder = new TextEncoder();

  let sendingHistory = true;
  let lastSentSeq = lastEventId ?? 0;
  const queue: Message[] = [];

  const formatSSE = (msg: Message): string => {
    const jsonStr = JSON.stringify({
      room: msg.room,
      seq: msg.seq,
      user: msg.user,
      text: msg.text,
      ts: msg.ts
    });
    return `id: ${msg.seq}\nevent: message\ndata: ${jsonStr}\n\n`;
  };

  const writeMsg = async (msg: Message) => {
    await writer.write(encoder.encode(formatSSE(msg)));
    lastSentSeq = msg.seq;
  };

  return new Promise<void>((resolve) => {
    let isProcessing = false;
    let resolved = false;

    const cleanup = () => {
      if (resolved) return;
      resolved = true;
      unsubscribe();
      try {
        writer.releaseLock();
      } catch (_) {}
      resolve();
    };

    const processQueue = async () => {
      if (isProcessing || resolved) return;
      isProcessing = true;
      try {
        while (queue.length > 0 && !resolved) {
          const msg = queue.shift()!;
          if (msg.seq > lastSentSeq) {
            await writeMsg(msg);
          }
        }
      } catch (err) {
        cleanup();
      } finally {
        isProcessing = false;
      }
    };

    const unsubscribe = subscribe(room, (msg) => {
      queue.push(msg);
      if (!sendingHistory) {
        processQueue();
      }
    });

    signal.addEventListener("abort", cleanup);

    // Self-executing async function to send history and transition to live mode
    (async () => {
      try {
        for (const msg of initialMessages) {
          if (resolved) return;
          if (msg.seq > lastSentSeq) {
            await writeMsg(msg);
          }
        }
        sendingHistory = false;
        await processQueue();
      } catch (err) {
        cleanup();
      }
    })();
  });
};

